import {ikariEnvironment} from '$lib/actions/ikari-environment';
export let data:PageData;
let copied=false;
async function copyDiscord(){try{await navigator.clipboard.writeText('aql.ikari');copied=true;}catch{copied=false;}}
</script>
<svelte:head><title>Conexões — Ikari</title><meta name="description" content="O canal, as publicações e o arquivo de cenas de Ikari. Uma nova ideia começa por aqui."/></svelte:head>
<section class="connections" use:chapterMotion use:ikariEnvironment>
 <div class="connections-back" aria-hidden="true"><span data-environment-layer>繋がり</span><svg viewBox="0 0 1200 1000" preserveAspectRatio="none"><path use:elasticWire data-environment-path d="M20 160 Q700 10 1030 360 T420 680 Q-100 800 1050 930"/></svg></div>
 <header class="connections-heading"><span class="studio-meta">IKARI / FORA DO QUADRO</span><h1 data-chapter-title>Conexões<span>.</span></h1><p data-chapter-piece>Entre uma cena e a próxima,<br/>é aqui que a gente se encontra.</p></header>
 <div class="connection-grid">
  <a class="connection-card connection-youtube" href={ikariChannelUrl} target="_blank" rel="noopener noreferrer" use:studioPointer={'tilt'} use:studioAmbient><div data-pointer-surface><span class="connection-pin"></span><div class="connection-top"><img class="network-icon" src="/ikari/brands/youtube.svg" alt="" width="32" height="32"/><span class="connection-stamp">CANAL / YOUTUBE ↗</span></div><h2>Bastidores.<br/>Sem cortar nada.</h2><div class="channel-deck">{#each ikariChannelVideos as video,i}<img src={video.cover} alt={video.title} width="480" height="270" loading="lazy" style={`--card:${i}`} data-studio-float/>{/each}</div><p>O processo por trás das edições.</p><span class="connection-arrow">Entrar no canal ↗</span></div></a>
  <a class="connection-card connection-x" href="https://x.com/ikarikjkk" target="_blank" rel="noopener noreferrer" use:studioPointer={'tilt'} use:studioAmbient><div data-pointer-surface><span class="connection-pin"></span><div class="connection-top"><img class="network-icon" src="/ikari/brands/x.svg" alt="" width="32" height="32"/><span class="connection-stamp">PUBLICAÇÕES / X ↗</span></div><h2>A cena<br/>em construção.</h2><img class="connection-banner" src="/ikari/banner-mural-small-v09.webp" alt="Banner ilustrado de Ikari" width="640" height="360" loading="lazy"/><p>Comissões, cortes e publicações de Ikari.</p><span class="connection-arrow">@ikarikjkk ↗</span></div></a>
